const express = require("express");
const app = express();
app.use(express.json());

function auth(req, res, next) {
  const [skema, token] = (req.headers.authorization || "").split(" ");
  const payload = skema === "Bearer" ? verifikasi(token) : null;
  if (!payload) return res.status(401).json({ error: "Belum login" });
  req.user = { id: payload.sub, role: payload.role };
  next();
}

function perluRole(role) {
  return (req, res, next) => {
    if (req.user.role !== role) return res.status(403).json({ error: "Dilarang" });
    next();
  };
}

app.post("/login", (req, res) => {
  const { email, password } = req.body;
  const user = USERS.find((u) => u.email === email);
  if (!user || user.hash !== hash(password || "")) {
    return res.status(401).json({ error: "Email atau password salah" });
  }
  res.json({ token: buatToken(user) });
});

app.get("/catatan", auth, (req, res) => {
  res.json(catatan.filter((c) => c.pemilik === req.user.id));
});

app.get("/catatan/:id", auth, (req, res) => {
  const c = catatan.find((x) => x.id === Number(req.params.id));
  if (!c || c.pemilik !== req.user.id) return res.status(404).json({ error: "Tidak ada" });
  res.json(c);
});

app.post("/catatan", auth, (req, res) => {
  const { judul, isi } = req.body;
  const errors = [];
  if (typeof judul !== "string" || judul.trim().length < 1 || judul.trim().length > 100) {
    errors.push("judul harus teks 1 sampai 100 karakter");
  }
  if (typeof isi !== "string") errors.push("isi harus berupa teks");
  if (errors.length) return res.status(400).json({ errors });
  const baru = { id: catatan.length + 1, pemilik: req.user.id, judul: judul.trim(), isi };
  catatan.push(baru);
  res.status(201).json(baru);
});

app.delete("/catatan/:id", auth, (req, res) => {
  const i = catatan.findIndex((c) => c.id === Number(req.params.id));
  const c = catatan[i];
  if (!c || (c.pemilik !== req.user.id && req.user.role !== "admin")) {
    return res.status(404).json({ error: "Tidak ada" });
  }
  catatan.splice(i, 1);
  res.json({ dihapus: c.id });
});

app.get("/admin/pengguna", auth, perluRole("admin"), (req, res) => {
  res.json(USERS.map((u) => ({ id: u.id, nama: u.nama, email: u.email, role: u.role })));
});

