const ABC = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
function b64url(s) {
  let out = "";
  for (let i = 0; i < s.length; i += 3) {
    const n = (s.charCodeAt(i) << 16) | ((s.charCodeAt(i + 1) || 0) << 8) | (s.charCodeAt(i + 2) || 0);
    out += ABC[(n >> 18) & 63] + ABC[(n >> 12) & 63];
    if (i + 1 < s.length) out += ABC[(n >> 6) & 63];
    if (i + 2 < s.length) out += ABC[n & 63];
  }
  return out;
}
function unb64url(t) {
  let bits = 0, acc = 0, out = "";
  for (const ch of t) {
    acc = (acc << 6) | ABC.indexOf(ch);
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      out += String.fromCharCode((acc >> bits) & 255);
      acc &= (1 << bits) - 1;
    }
  }
  return out;
}
function sign(data, secret) {
  let h = 2166136261;
  const s = secret + "." + data + "." + secret;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return ("00000000" + h.toString(16)).slice(-8);
}
const encode = (obj) => b64url(JSON.stringify(obj));
const decode = (str) => JSON.parse(unb64url(str));
// Pengganti hash lambat untuk latihan (FNV-1a), bukan untuk produksi.
function hash(teks) {
  let h = 2166136261;
  for (let i = 0; i < teks.length; i++) {
    h ^= teks.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return ("00000000" + h.toString(16)).slice(-8);
}

const SECRET = "rahasia-proyek-yang-cukup-panjang-0123456789";
const SEKARANG = 1000; // jam tetap untuk latihan

function buatToken(user, ttl = 900) {
  const header = { alg: "HS256", typ: "JWT" };
  const klaim = { sub: user.id, role: user.role, iat: SEKARANG, exp: SEKARANG + ttl };
  const data = encode(header) + "." + encode(klaim);
  return data + "." + sign(data, SECRET);
