// Mengembalikan payload bila token sah, selain itu null.
function verifikasi(token) {
  if (typeof token !== "string") return null;
  const bagian = token.split(".");
  if (bagian.length !== 3) return null;
  const [h, p, s] = bagian;
  if (s !== sign(h + "." + p, SECRET)) return null;
  const payload = decode(p);
  return SEKARANG < payload.exp ? payload : null;
}

